<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue'
import type {Stage45Api,Message,Page} from '../../../business-common/stage45/types'
import {date,label} from '../../../business-common/stage45/presentation'
import BaseCard from '../BaseCard.vue'
import AppButton from '../AppButton.vue'
const props=defineProps<{api:Stage45Api;merchant?:boolean;refreshKey?:number}>()
const rows=ref<Message[]>([]),todos=ref<{state:string;count:number}[]>([]),page=ref(1),total=ref(0),loading=ref(false),error=ref('')
let ticket=0
async function load(){const run=++ticket,owner=props.api.owner();loading.value=true;error.value='';try{const result=await props.api.read<Page<Message>&{todos:{state:string;count:number}[]}>('/messages',{pageNumber:page.value,pageSize:20});if(run===ticket&&owner===props.api.owner()){rows.value=result.records;total.value=result.total;todos.value=result.todos}}catch(e){if(run===ticket){rows.value=[];todos.value=[];error.value=e instanceof Error?e.message:'消息读取失败。'}}finally{if(run===ticket)loading.value=false}}
async function open(row:Message){const owner=props.api.owner();try{await props.api.markRead(row.id);if(owner!==props.api.owner())return;row.read=true;const kind=row.subjectType;const url=kind==='AFTERSALE'?'/pages/after-sale/detail/index?id='+row.subjectId:kind==='EVALUATION'?(props.merchant?'/pages/evaluation/index':'/pages/evaluation/index?id='+row.subjectId):props.merchant&&kind==='FUNDS'?'/pages/funds/detail/index?id='+row.orderId:(props.merchant?'/pages/order/detail/index?id=':'/pages/mall/order-detail/index?id=')+row.orderId;uni.navigateTo({url})}catch(e){error.value=e instanceof Error?e.message:'当前身份不能访问此记录。'}}
function openTodo(state:string){if(props.merchant)uni.navigateTo({url:state.startsWith('FUNDS_')?'/pages/funds/index':'/pages/after-sale/index'})}
watch(()=>props.api.owner(),()=>{ticket++;rows.value=[];todos.value=[];page.value=1;load()},{immediate:true});watch(()=>props.refreshKey,load);onBeforeUnmount(()=>{ticket++;rows.value=[];todos.value=[]})
</script>
<template><view class="s45"><BaseCard v-if="todos.length"><text class="section">{{merchant?'当前业务与资金待办':'当前售后待办'}}</text><view v-for="item in todos" :key="item.state" class="row"><text>{{label(item.state)}}</text><text>{{item.count}} 项</text><AppButton class="s45-action" v-if="merchant" size="compact" variant="secondary" @click="openTodo(item.state)">查看待办</AppButton></view><text class="muted">待办取自当前业务状态，历史消息不代表当前结果。</text></BaseCard><BaseCard v-if="error"><text class="error" role="alert">{{error}}</text><AppButton class="s45-action" variant="secondary" @click="load">重新读取</AppButton></BaseCard><text v-if="loading" class="state">正在读取商城消息…</text><BaseCard v-for="row in rows" :key="row.id"><view class="row"><text class="strong">{{row.title}}</text><text class="badge">{{row.read?'已读':'未读'}}</text></view><text>{{row.content}}</text><text class="muted">{{row.storeName}} · 订单 {{row.orderSn}}</text><text class="muted">{{date(row.at)}}</text><AppButton class="s45-action" variant="secondary" @click="open(row)">查看当前详情</AppButton></BaseCard><BaseCard v-if="!loading&&!error&&!rows.length"><text class="state">暂无商城消息。</text></BaseCard><view v-if="total" class="buttons"><AppButton class="s45-action" variant="secondary" :disabled="loading||page<=1" @click="page--;load()">上一页</AppButton><text>{{page}} 页 · {{total}} 条</text><AppButton class="s45-action" variant="secondary" :disabled="loading||page*20>=total" @click="page++;load()">下一页</AppButton></view></view></template>
<style scoped lang="scss">@import './stage45.scss';</style>
